    "responseSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"DuctFamilyPatchData\",\r\n  \"type\": \"object\",\r\n  \"description\": \"Patch is the FamilyPatch JSON as `families.plan` reads it; Rows counts the table; Sources names the ASHRAE grids behind it.\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"patch\",\r\n    \"table\",\r\n    \"rows\",\r\n    \"sources\",\r\n    \"formula\"\r\n  ],\r\n  \"properties\": {\r\n    \"patch\": {},\r\n    \"table\": {\r\n      \"type\": \"string\"\r\n    },\r\n    \"rows\": {\r\n      \"type\": \"integer\",\r\n      \"format\": \"int32\"\r\n    },\r\n    \"sources\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"type\": \"string\"\r\n      }\r\n    },\r\n    \"formula\": {\r\n      \"type\": \"string\"\r\n    }\r\n  }\r\n}",
