    "responseSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"FamiliesCaptureData\",\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"families\",\r\n    \"diagnostics\"\r\n  ],\r\n  \"properties\": {\r\n    \"families\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"$ref\": \"#/definitions/FamilyFoundryFamilyModelData\"\r\n      }\r\n    },\r\n    \"diagnostics\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"$ref\": \"#/definitions/FamilyFoundryDiagnostic\"\r\n      }\r\n    }\r\n  },\r\n  \"definitions\": {\r\n    \"FamilyFoundryFamilyModelData\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"familyId\",\r\n        \"success\",\r\n        \"coverage\",\r\n        \"unmodeledCount\",\r\n        \"issues\"\r\n      ],\r\n      \"properties\": {\r\n        \"familyId\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int64\"\r\n        },\r\n        \"familyName\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"success\": {\r\n          \"type\": \"boolean\"\r\n        },\r\n        \"modelJson\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"coverage\": {\r\n          \"type\": \"object\",\r\n          \"additionalProperties\": {\r\n            \"type\": \"string\"\r\n          }\r\n        },\r\n        \"unmodeledCount\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int32\"\r\n        },\r\n        \"issues\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"$ref\": \"#/definitions/RevitDataIssue\"\r\n          }\r\n        },\r\n        \"error\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        }\r\n      }\r\n    },\r\n    \"RevitDataIssue\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"code\",\r\n        \"severity\",\r\n        \"message\"\r\n      ],\r\n      \"properties\": {\r\n        \"code\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"severity\": {\r\n          \"$ref\": \"#/definitions/RevitDataIssueSeverity\"\r\n        },\r\n        \"message\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"familyName\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"typeName\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"parameterName\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        }\r\n      }\r\n    },\r\n    \"RevitDataIssueSeverity\": {\r\n      \"type\": \"string\",\r\n      \"description\": \"\",\r\n      \"x-enumNames\": [\r\n        \"Info\",\r\n        \"Warning\",\r\n        \"Error\"\r\n      ],\r\n      \"enum\": [\r\n        \"Info\",\r\n        \"Warning\",\r\n        \"Error\"\r\n      ]\r\n    },\r\n    \"FamilyFoundryDiagnostic\": {\r\n      \"type\": \"object\",\r\n      \"description\": \"Diagnostic for the Family Foundry host operations: a closed code, a JSON path, a message, an optional fix.\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"code\",\r\n        \"path\",\r\n        \"message\"\r\n      ],\r\n      \"properties\": {\r\n        \"code\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"path\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"message\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"suggestion\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        }\r\n      }\r\n    }\r\n  }\r\n}",
