    "needs": "nothing",
    "description": "Build a new Revit family from a saved family model spec by reconciling a fresh document from the spec's template. The .rfa lands in a fresh run folder in the source pod beside the run receipt; the operation returns both paths.",
    "searchTerms": [
      "family",
      "family-json",
      "build",
      "template",
      "spec",
      "receipt"
    ],
    "requestExamples": [],
    "safeDefaultRequestJson": "{}",
    "callGuidance": [],
    "requestSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"FamilyBuildRequest\",\r\n  \"type\": \"object\",\r\n  \"description\": \"Build a new family from a saved family model spec on its header's template; nested models resolve\\nfrom `modelDirectory`. There is no output path: every build lands in a fresh run folder in the source\\npod beside its receipt (user verdict, 2026-09-17), so nothing overwrites and nothing escapes the pod.\\n            \",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"specJson\",\r\n    \"source\"\r\n  ],\r\n  \"properties\": {\r\n    \"specJson\": {\r\n      \"type\": \"string\"\r\n    },\r\n    \"source\": {\r\n      \"$ref\": \"#/definitions/PodComposedSource\"\r\n    },\r\n    \"modelDirectory\": {\r\n      \"type\": [\r\n        \"null\",\r\n        \"string\"\r\n      ]\r\n    }\r\n  },\r\n  \"definitions\": {\r\n    \"PodComposedSource\": {\r\n      \"type\": \"object\",\r\n      \"description\": \"The exact bytes one composition consumed, captured at its one read: the root (a saved member or a supplied\\ndraft, with a pod id only when composition has actual pod context) and its ordered dependencies. A run stores these bytes; it never rereads them.\\n            \",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"root\",\r\n        \"dependencies\"\r\n      ],\r\n      \"properties\": {\r\n        \"root\": {\r\n          \"$ref\": \"#/definitions/PodCapturedSourceData\"\r\n        },\r\n        \"dependencies\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"$ref\": \"#/definitions/PodConsumedSourceData\"\r\n          }\r\n        }\r\n      }\r\n    },\r\n    \"PodCapturedSourceData\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"path\",\r\n        \"sha256\",\r\n        \"bytesBase64\",\r\n        \"origin\"\r\n      ],\r\n      \"properties\": {\r\n        \"id\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"path\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"sha256\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"bytesBase64\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"origin\": {\r\n          \"$ref\": \"#/definitions/PodRunOrigin\"\r\n        }\r\n      }\r\n    },\r\n    \"PodRunOrigin\": {\r\n      \"type\": \"string\",\r\n      \"description\": \"What a run's source was: a saved member's bytes, a supplied draft, or operation input with no member.\",\r\n      \"x-enumNames\": [\r\n        \"SavedMember\",\r\n        \"SuppliedDraft\",\r\n        \"Operation\"\r\n      ],\r\n      \"enum\": [\r\n        \"SavedMember\",\r\n        \"SuppliedDraft\",\r\n        \"Operation\"\r\n      ]\r\n    },\r\n    \"PodConsumedSourceData\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"id\",\r\n        \"path\",\r\n        \"sha256\",\r\n        \"bytesBase64\"\r\n      ],\r\n      \"properties\": {\r\n        \"id\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"path\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"sha256\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"bytesBase64\": {\r\n          \"type\": \"string\"\r\n        }\r\n      }\r\n    }\r\n  }\r\n}",
    "responseSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"FamilyBuildData\",\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"reading\",\r\n    \"familyName\",\r\n    \"outputPath\",\r\n    \"templatePath\",\r\n    \"converged\",\r\n    \"residueCount\"\r\n  ],\r\n  \"properties\": {\r\n    \"reading\": {\r\n      \"$ref\": \"#/definitions/Reading\"\r\n    },\r\n    \"familyName\": {\r\n      \"type\": \"string\"\r\n    },\r\n    \"outputPath\": {\r\n      \"type\": \"string\"\r\n    },\r\n    \"templatePath\": {\r\n      \"type\": \"string\"\r\n    },\r\n    \"converged\": {\r\n      \"type\": \"boolean\"\r\n    },\r\n    \"residueCount\": {\r\n      \"type\": \"integer\",\r\n      \"format\": \"int32\"\r\n    },\r\n    \"receiptPath\": {\r\n      \"type\": [\r\n        \"null\",\r\n        \"string\"\r\n      ]\r\n    },\r\n    \"outputError\": {\r\n      \"type\": [\r\n        \"null\",\r\n        \"string\"\r\n      ]\r\n    }\r\n  },\r\n  \"definitions\": {\r\n    \"Reading\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"at\",\r\n        \"observedAt\"\r\n      ],\r\n      \"properties\": {\r\n        \"at\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"version\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"observedAt\": {\r\n          \"type\": \"string\"\r\n        }\r\n      }\r\n    }\r\n  }\r\n}",
    "actor": "any",
