    "displayName": "Capture Family",
    "intent": "Read",
    "costTier": "Bounded",
    "visibility": "EscalationVisible",
    "needs": "family-document",
    "description": "Capture the active Revit family document as a family.json spec, with per-section coverage and the unmodeled ledger.",
    "searchTerms": [
      "family",
      "family-json",
      "capture",
      "spec",
      "coverage"
    ],
    "requestExamples": [],
    "safeDefaultRequestJson": "{}",
