    "requestSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"FamilyLookRequest\",\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"outDir\"\r\n  ],\r\n  \"properties\": {\r\n    \"outDir\": {\r\n      \"type\": \"string\"\r\n    },\r\n    \"types\": {\r\n      \"type\": [\r\n        \"array\",\r\n        \"null\"\r\n      ],\r\n      \"items\": {\r\n        \"type\": \"string\"\r\n      }\r\n    },\r\n    \"toggles\": {\r\n      \"type\": [\r\n        \"array\",\r\n        \"null\"\r\n      ],\r\n      \"items\": {\r\n        \"type\": \"string\"\r\n      }\r\n    }\r\n  }\r\n}",
    "responseSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"FamilyLookData\",\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"rows\"\r\n  ],\r\n  \"properties\": {\r\n    \"rows\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"$ref\": \"#/definitions/FamilyLookRow\"\r\n      }\r\n    }\r\n  },\r\n  \"definitions\": {\r\n    \"FamilyLookRow\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"type\",\r\n        \"state\",\r\n        \"elements\",\r\n        \"images\"\r\n      ],\r\n      \"properties\": {\r\n        \"type\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"state\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"elements\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"$ref\": \"#/definitions/FamilyLookElement\"\r\n          }\r\n        },\r\n        \"images\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"$ref\": \"#/definitions/FamilyVerifyImage\"\r\n          }\r\n        }\r\n      }\r\n    },\r\n    \"FamilyLookElement\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"id\",\r\n        \"kind\",\r\n        \"name\",\r\n        \"visible\"\r\n      ],\r\n      \"properties\": {\r\n        \"id\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int64\"\r\n        },\r\n        \"kind\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"name\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"visible\": {\r\n          \"type\": \"boolean\"\r\n        },\r\n        \"bounds\": {\r\n          \"oneOf\": [\r\n            {\r\n              \"type\": \"null\"\r\n            },\r\n            {\r\n              \"$ref\": \"#/definitions/FamilyVerifyBounds\"\r\n            }\r\n          ]\r\n        },\r\n        \"connector\": {\r\n          \"oneOf\": [\r\n            {\r\n              \"type\": \"null\"\r\n            },\r\n            {\r\n              \"$ref\": \"#/definitions/FamilyVerifyConnector\"\r\n            }\r\n          ]\r\n        }\r\n      }\r\n    },\r\n    \"FamilyVerifyBounds\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"min\",\r\n        \"max\"\r\n      ],\r\n      \"properties\": {\r\n        \"min\": {\r\n          \"$ref\": \"#/definitions/FamilyVerifyPoint\"\r\n        },\r\n        \"max\": {\r\n          \"$ref\": \"#/definitions/FamilyVerifyPoint\"\r\n        }\r\n      }\r\n    },\r\n    \"FamilyVerifyPoint\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"x\",\r\n        \"y\",\r\n        \"z\"\r\n      ],\r\n      \"properties\": {\r\n        \"x\": {\r\n          \"type\": \"number\",\r\n          \"format\": \"double\"\r\n        },\r\n        \"y\": {\r\n          \"type\": \"number\",\r\n          \"format\": \"double\"\r\n        },\r\n        \"z\": {\r\n          \"type\": \"number\",\r\n          \"format\": \"double\"\r\n        }\r\n      }\r\n    },\r\n    \"FamilyVerifyConnector\": {\r\n      \"type\": \"object\",\r\n      \"description\": \"Positions and sizes are inches; normals are unit vectors. Direction is In, Out, Bidirectional, or null when the domain has none.\\n            Drives maps a connector parameter (Flow, Width, Voltage...) to the family parameter associated with it; family documents only.\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"domain\",\r\n        \"system\",\r\n        \"origin\",\r\n        \"normal\",\r\n        \"shape\"\r\n      ],\r\n      \"properties\": {\r\n        \"domain\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"system\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"origin\": {\r\n          \"$ref\": \"#/definitions/FamilyVerifyPoint\"\r\n        },\r\n        \"normal\": {\r\n          \"$ref\": \"#/definitions/FamilyVerifyPoint\"\r\n        },\r\n        \"shape\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"diameter\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"number\"\r\n          ],\r\n          \"format\": \"double\"\r\n        },\r\n        \"width\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"number\"\r\n          ],\r\n          \"format\": \"double\"\r\n        },\r\n        \"height\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"number\"\r\n          ],\r\n          \"format\": \"double\"\r\n        },\r\n        \"direction\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"drives\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"object\"\r\n          ],\r\n          \"additionalProperties\": {\r\n            \"type\": \"string\"\r\n          }\r\n        }\r\n      }\r\n    },\r\n    \"FamilyVerifyImage\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"view\",\r\n        \"path\"\r\n      ],\r\n      \"properties\": {\r\n        \"view\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"path\": {\r\n          \"type\": \"string\"\r\n        }\r\n      }\r\n    }\r\n  }\r\n}",
