    "responseSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"HostOpsCatalogData\",\r\n  \"type\": \"object\",\r\n  \"description\": \"The op catalog plus the contract constants typegen emits as `export const`s.\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"operations\",\r\n    \"constants\"\r\n  ],\r\n  \"properties\": {\r\n    \"operations\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"$ref\": \"#/definitions/HostOpsCatalogEntry\"\r\n      }\r\n    },\r\n    \"constants\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": {\r\n        \"type\": \"object\",\r\n        \"additionalProperties\": {}\r\n      }\r\n    }\r\n  },\r\n  \"definitions\": {\r\n    \"HostOpsCatalogEntry\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"key\",\r\n        \"intent\",\r\n        \"costTier\",\r\n        \"visibility\",\r\n        \"needs\",\r\n        \"description\",\r\n        \"searchTerms\",\r\n        \"requestExamples\",\r\n        \"callGuidance\",\r\n        \"requestSchemaJson\",\r\n        \"responseSchemaJson\",\r\n        \"actor\",\r\n        \"usesTransactions\"\r\n      ],\r\n      \"properties\": {\r\n        \"key\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"displayName\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"intent\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"costTier\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"visibility\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"needs\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"description\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"searchTerms\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"type\": \"string\"\r\n          }\r\n        },\r\n        \"requestExamples\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"$ref\": \"#/definitions/HostOperationRequestExample\"\r\n          }\r\n        },\r\n        \"safeDefaultRequestJson\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"callGuidance\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"type\": \"string\"\r\n          }\r\n        },\r\n        \"requestSchemaJson\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"responseSchemaJson\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"actor\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"usesTransactions\": {\r\n          \"type\": \"boolean\"\r\n        }\r\n      }\r\n    },\r\n    \"HostOperationRequestExample\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"name\",\r\n        \"description\",\r\n        \"json\"\r\n      ],\r\n      \"properties\": {\r\n        \"name\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"description\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"json\": {\r\n          \"type\": \"string\"\r\n        }\r\n      }\r\n    }\r\n  }\r\n}",
