    "responseSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"PodMemberComposeData\",\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"source\",\r\n    \"diagnostics\",\r\n    \"dependencies\"\r\n  ],\r\n  \"properties\": {\r\n    \"composed\": {\r\n      \"type\": [\r\n        \"null\",\r\n        \"string\"\r\n      ]\r\n    },\r\n    \"source\": {\r\n      \"$ref\": \"#/definitions/PodCapturedSourceData\"\r\n    },\r\n    \"diagnostics\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"$ref\": \"#/definitions/ScriptDiagnostic\"\r\n      }\r\n    },\r\n    \"dependencies\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"$ref\": \"#/definitions/PodConsumedSourceData\"\r\n      }\r\n    }\r\n  },\r\n  \"definitions\": {\r\n    \"PodCapturedSourceData\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"path\",\r\n        \"sha256\",\r\n        \"bytesBase64\",\r\n        \"origin\"\r\n      ],\r\n      \"properties\": {\r\n        \"id\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        },\r\n        \"path\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"sha256\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"bytesBase64\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"origin\": {\r\n          \"$ref\": \"#/definitions/PodRunOrigin\"\r\n        }\r\n      }\r\n    },\r\n    \"PodRunOrigin\": {\r\n      \"type\": \"string\",\r\n      \"description\": \"What a run's source was: a saved member's bytes, a supplied draft, or operation input with no member.\",\r\n      \"x-enumNames\": [\r\n        \"SavedMember\",\r\n        \"SuppliedDraft\",\r\n        \"Operation\"\r\n      ],\r\n      \"enum\": [\r\n        \"SavedMember\",\r\n        \"SuppliedDraft\",\r\n        \"Operation\"\r\n      ]\r\n    },\r\n    \"ScriptDiagnostic\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"stage\",\r\n        \"severity\",\r\n        \"message\"\r\n      ],\r\n      \"properties\": {\r\n        \"stage\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"severity\": {\r\n          \"$ref\": \"#/definitions/ScriptDiagnosticSeverity\"\r\n        },\r\n        \"message\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"source\": {\r\n          \"type\": [\r\n            \"null\",\r\n            \"string\"\r\n          ]\r\n        }\r\n      }\r\n    },\r\n    \"ScriptDiagnosticSeverity\": {\r\n      \"type\": \"string\",\r\n      \"description\": \"\",\r\n      \"x-enumNames\": [\r\n        \"Info\",\r\n        \"Warning\",\r\n        \"Error\"\r\n      ],\r\n      \"enum\": [\r\n        \"Info\",\r\n        \"Warning\",\r\n        \"Error\"\r\n      ]\r\n    },\r\n    \"PodConsumedSourceData\": {\r\n      \"type\": \"object\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"id\",\r\n        \"path\",\r\n        \"sha256\",\r\n        \"bytesBase64\"\r\n      ],\r\n      \"properties\": {\r\n        \"id\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"path\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"sha256\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"bytesBase64\": {\r\n          \"type\": \"string\"\r\n        }\r\n      }\r\n    }\r\n  }\r\n}",
