    "responseSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"RevitWarningsListData\",\r\n  \"type\": \"object\",\r\n  \"description\": \"What revit.catalog.warnings read.\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"count\",\r\n    \"rows\"\r\n  ],\r\n  \"properties\": {\r\n    \"count\": {\r\n      \"type\": \"integer\",\r\n      \"description\": \"How many warnings the document holds.\",\r\n      \"format\": \"int32\"\r\n    },\r\n    \"rows\": {\r\n      \"type\": \"array\",\r\n      \"description\": \"Every warning, in the order Revit reports them.\",\r\n      \"items\": {\r\n        \"$ref\": \"#/definitions/RevitWarningRow\"\r\n      }\r\n    }\r\n  },\r\n  \"definitions\": {\r\n    \"RevitWarningRow\": {\r\n      \"type\": \"object\",\r\n      \"description\": \"One warning the document holds, as Revit's Review Warnings dialog lists it.\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"severity\",\r\n        \"description\",\r\n        \"elementIds\",\r\n        \"additionalElementIds\"\r\n      ],\r\n      \"properties\": {\r\n        \"severity\": {\r\n          \"type\": \"string\",\r\n          \"description\": \"Revit's severity name: Warning, Error, or DocumentCorruption.\"\r\n        },\r\n        \"description\": {\r\n          \"type\": \"string\",\r\n          \"description\": \"The warning text.\"\r\n        },\r\n        \"elementIds\": {\r\n          \"type\": \"array\",\r\n          \"description\": \"Ids of the elements the warning is about.\",\r\n          \"items\": {\r\n            \"type\": \"integer\",\r\n            \"format\": \"int64\"\r\n          }\r\n        },\r\n        \"additionalElementIds\": {\r\n          \"type\": \"array\",\r\n          \"description\": \"Ids of elements Revit lists alongside, such as the other side of a join or overlap.\",\r\n          \"items\": {\r\n            \"type\": \"integer\",\r\n            \"format\": \"int64\"\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n}",
