    "requestSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"RevitAgentViewRenderingStateRequest\",\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"properties\": {\r\n    \"scope\": {\r\n      \"$ref\": \"#/definitions/RevitAgentViewRenderingScope\"\r\n    },\r\n    \"viewIds\": {\r\n      \"type\": [\r\n        \"array\",\r\n        \"null\"\r\n      ],\r\n      \"items\": {\r\n        \"type\": \"integer\",\r\n        \"format\": \"int64\"\r\n      }\r\n    },\r\n    \"viewUniqueIds\": {\r\n      \"type\": [\r\n        \"array\",\r\n        \"null\"\r\n      ],\r\n      \"items\": {\r\n        \"type\": \"string\"\r\n      }\r\n    },\r\n    \"maxViews\": {\r\n      \"type\": [\r\n        \"integer\",\r\n        \"null\"\r\n      ],\r\n      \"format\": \"int32\"\r\n    },\r\n    \"maxFiltersPerView\": {\r\n      \"type\": [\r\n        \"integer\",\r\n        \"null\"\r\n      ],\r\n      \"format\": \"int32\"\r\n    },\r\n    \"maxHiddenCategoriesPerView\": {\r\n      \"type\": [\r\n        \"integer\",\r\n        \"null\"\r\n      ],\r\n      \"format\": \"int32\"\r\n    },\r\n    \"maxLinksPerView\": {\r\n      \"type\": [\r\n        \"integer\",\r\n        \"null\"\r\n      ],\r\n      \"format\": \"int32\"\r\n    },\r\n    \"maxWorksetsPerView\": {\r\n      \"type\": [\r\n        \"integer\",\r\n        \"null\"\r\n      ],\r\n      \"format\": \"int32\"\r\n    }\r\n  },\r\n  \"definitions\": {\r\n    \"RevitAgentViewRenderingScope\": {\r\n      \"type\": \"string\",\r\n      \"description\": \"\",\r\n      \"x-enumNames\": [\r\n        \"ActiveView\",\r\n        \"ViewReferences\"\r\n      ],\r\n      \"enum\": [\r\n        \"ActiveView\",\r\n        \"ViewReferences\"\r\n      ]\r\n    }\r\n  }\r\n}",
