    "requestSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"TreeRequest\",\r\n  \"type\": \"object\",\r\n  \"description\": \"Read Source's BVH through MaxDepth inclusive. Source defaults to host (0), depth to 8.\",\r\n  \"additionalProperties\": false,\r\n  \"properties\": {\r\n    \"source\": {\r\n      \"type\": [\r\n        \"integer\",\r\n        \"null\"\r\n      ],\r\n      \"format\": \"int32\"\r\n    },\r\n    \"maxDepth\": {\r\n      \"type\": [\r\n        \"integer\",\r\n        \"null\"\r\n      ],\r\n      \"format\": \"int32\"\r\n    }\r\n  }\r\n}",
    "responseSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"TreeAnswer\",\r\n  \"type\": \"object\",\r\n  \"description\": \"One source BVH, through MaxDepth inclusive, in post-order with the root last.\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"stamp\",\r\n    \"source\",\r\n    \"maxDepth\",\r\n    \"nodes\",\r\n    \"ms\"\r\n  ],\r\n  \"properties\": {\r\n    \"stamp\": {\r\n      \"$ref\": \"#/definitions/Stamp\"\r\n    },\r\n    \"source\": {\r\n      \"type\": \"integer\",\r\n      \"format\": \"int32\"\r\n    },\r\n    \"maxDepth\": {\r\n      \"type\": \"integer\",\r\n      \"format\": \"int32\"\r\n    },\r\n    \"nodes\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"$ref\": \"#/definitions/BvhNode\"\r\n      }\r\n    },\r\n    \"ms\": {\r\n      \"type\": \"number\",\r\n      \"format\": \"double\"\r\n    }\r\n  },\r\n  \"definitions\": {\r\n    \"Stamp\": {\r\n      \"type\": \"object\",\r\n      \"description\": \"Provenance and freshness. Every answer embeds one; it is not optional.\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"hostDocumentKey\",\r\n        \"epoch\",\r\n        \"frame\",\r\n        \"builtUtc\",\r\n        \"sources\",\r\n        \"fresh\",\r\n        \"resolved\"\r\n      ],\r\n      \"properties\": {\r\n        \"hostDocumentKey\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"epoch\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int64\"\r\n        },\r\n        \"frame\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"builtUtc\": {\r\n          \"type\": \"string\",\r\n          \"format\": \"date-time\"\r\n        },\r\n        \"sources\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"$ref\": \"#/definitions/SourceRow\"\r\n          }\r\n        },\r\n        \"fresh\": {\r\n          \"type\": \"boolean\"\r\n        },\r\n        \"resolved\": {\r\n          \"$ref\": \"#/definitions/Resolved\"\r\n        }\r\n      }\r\n    },\r\n    \"SourceRow\": {\r\n      \"type\": \"object\",\r\n      \"description\": \"One row per partition. Carried inside every Stamp.\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"source\",\r\n        \"documentKey\",\r\n        \"kind\",\r\n        \"builtAtEpoch\",\r\n        \"dirty\",\r\n        \"elements\",\r\n        \"triangles\",\r\n        \"skipped\"\r\n      ],\r\n      \"properties\": {\r\n        \"source\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int32\"\r\n        },\r\n        \"documentKey\": {\r\n          \"type\": \"string\"\r\n        },\r\n        \"linkInstanceId\": {\r\n          \"type\": [\r\n            \"integer\",\r\n            \"null\"\r\n          ],\r\n          \"format\": \"int64\"\r\n        },\r\n        \"kind\": {\r\n          \"$ref\": \"#/definitions/SourceKind\"\r\n        },\r\n        \"builtAtEpoch\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int64\"\r\n        },\r\n        \"dirty\": {\r\n          \"type\": \"boolean\"\r\n        },\r\n        \"elements\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int32\"\r\n        },\r\n        \"triangles\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int32\"\r\n        },\r\n        \"skipped\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int32\"\r\n        }\r\n      }\r\n    },\r\n    \"SourceKind\": {\r\n      \"type\": \"string\",\r\n      \"description\": \"Which document a partition reads. One partition per source.\",\r\n      \"x-enumNames\": [\r\n        \"Host\",\r\n        \"RevitLink\",\r\n        \"IfcLink\"\r\n      ],\r\n      \"enum\": [\r\n        \"Host\",\r\n        \"RevitLink\",\r\n        \"IfcLink\"\r\n      ]\r\n    },\r\n    \"Resolved\": {\r\n      \"type\": \"object\",\r\n      \"description\": \"The options a verb actually ran with, after defaults were applied. Never null and never a\\nsilence: a caller who passed no filter reads back Kinds: [Solid, Mesh] and the sources\\nand categories spelled out. This is the gate that was in force, not the outcome; what the\\nverb then had to touch is Searched.\\n            \",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"sources\",\r\n        \"categories\",\r\n        \"kinds\",\r\n        \"layers\",\r\n        \"excludedElementIds\"\r\n      ],\r\n      \"properties\": {\r\n        \"sources\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"$ref\": \"#/definitions/SourceKind\"\r\n          }\r\n        },\r\n        \"categories\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"type\": \"string\"\r\n          }\r\n        },\r\n        \"kinds\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"$ref\": \"#/definitions/PrimKind\"\r\n          }\r\n        },\r\n        \"layers\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"type\": \"string\"\r\n          }\r\n        },\r\n        \"excludedElementIds\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"type\": \"integer\",\r\n            \"format\": \"int64\"\r\n          }\r\n        }\r\n      }\r\n    },\r\n    \"PrimKind\": {\r\n      \"type\": \"string\",\r\n      \"description\": \"What a triangle came from. Curve2D is a DWG 2D layer raised into a vertical\\nribbon; it is never an obstructor unless a filter names it.\\n            \",\r\n      \"x-enumNames\": [\r\n        \"Solid\",\r\n        \"Mesh\",\r\n        \"Curve2D\",\r\n        \"Element\"\r\n      ],\r\n      \"enum\": [\r\n        \"Solid\",\r\n        \"Mesh\",\r\n        \"Curve2D\",\r\n        \"Element\"\r\n      ]\r\n    },\r\n    \"BvhNode\": {\r\n      \"type\": \"object\",\r\n      \"description\": \"One BVH node: its index, depth, leaf flag, subtree triangle count, and six host-feet bounds.\",\r\n      \"additionalProperties\": false,\r\n      \"required\": [\r\n        \"index\",\r\n        \"depth\",\r\n        \"leaf\",\r\n        \"triangles\",\r\n        \"box\"\r\n      ],\r\n      \"properties\": {\r\n        \"index\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int32\"\r\n        },\r\n        \"depth\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int32\"\r\n        },\r\n        \"leaf\": {\r\n          \"type\": \"boolean\"\r\n        },\r\n        \"triangles\": {\r\n          \"type\": \"integer\",\r\n          \"format\": \"int32\"\r\n        },\r\n        \"box\": {\r\n          \"type\": \"array\",\r\n          \"items\": {\r\n            \"type\": \"number\",\r\n            \"format\": \"float\"\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n}",
