    "requestSchemaJson": "{\r\n  \"$schema\": \"http://json-schema.org/draft-04/schema#\",\r\n  \"title\": \"FamilyInstanceReferencesRequest\",\r\n  \"type\": \"object\",\r\n  \"description\": \"Resolve current placements across every type of one exactly identified loaded family.\",\r\n  \"additionalProperties\": false,\r\n  \"required\": [\r\n    \"familyUniqueId\",\r\n    \"familyId\"\r\n  ],\r\n  \"properties\": {\r\n    \"familyId\": {\r\n      \"type\": \"integer\",\r\n      \"format\": \"int64\",\r\n      \"maximum\": 9007199254740991.0,\r\n      \"minimum\": 1.0\r\n    },\r\n    \"familyUniqueId\": {\r\n      \"type\": \"string\",\r\n      \"minLength\": 1,\r\n      \"pattern\": \".*\\\\S.*\"\r\n    },\r\n    \"maxResults\": {\r\n      \"type\": \"integer\",\r\n      \"format\": \"int32\",\r\n      \"default\": 500,\r\n      \"maximum\": 1000.0,\r\n      \"minimum\": 1.0\r\n    }\r\n  }\r\n}",
